_REPORT_KINDS = ("created", "shipped", "cancelled", "rejected")


class SimulationReport:
    """Plain result container for a simulation run."""

    def __init__(self) -> None:
        """Initialise all counters and revenue to zero."""
        self._counts: Dict[str, int] = {kind: 0 for kind in _REPORT_KINDS}
        self._revenue: Money = Money(0)

    @property
    def orders_created(self) -> int:
        """Return the number of orders created."""
        return self._counts["created"]

    @property
    def orders_shipped(self) -> int:
        """Return the number of orders shipped."""
        return self._counts["shipped"]

    @property
    def orders_cancelled(self) -> int:
        """Return the number of orders cancelled."""
        return self._counts["cancelled"]

    @property
    def rejected_out_of_stock(self) -> int:
        """Return the number of steps rejected for insufficient stock."""
        return self._counts["rejected"]

    @property
    def revenue(self) -> Money:
        """Return the total revenue earned by shipped orders."""
        return self._revenue

    def record(self, kind: str) -> None:
        """Increment the counter for ``kind``; raises if the kind is unknown."""
        if kind not in _REPORT_KINDS:
            raise ValueError(f"unknown report kind: {kind!r}")
        self._counts[kind] += 1

    def add_revenue(self, amount: Money) -> None:
        """Add ``amount`` to the total revenue."""
        if not isinstance(amount, Money):
            raise TypeError("amount must be Money")
        self._revenue = self._revenue + amount

    def summary(self) -> Dict[str, object]:
        """Return a dictionary summary of counts and formatted revenue."""
        return {
            "orders_created": self.orders_created,
            "orders_shipped": self.orders_shipped,
            "orders_cancelled": self.orders_cancelled,
            "rejected_out_of_stock": self.rejected_out_of_stock,
            "revenue": format_cents(self._revenue.cents),
        }

    def __str__(self) -> str:
        """Render the summary as one ``key: value`` line per entry."""
        return "\n".join(f"{key}: {value}" for key, value in self.summary().items())

class Product(Entity):
    """Catalog item."""

    def __init__(self, sku: str, name: str, category: Category, unit_price: Money) -> None:
        """Create a product after validating its SKU, name, category, and price."""
        sku = normalize_sku(sku)
        if not isinstance(name, str) or name.strip() == "":
            raise ValueError("name required")
        if not isinstance(category, Category):
            raise TypeError("category must be Category")
        if not isinstance(unit_price, Money):
            raise TypeError("unit_price must be Money")
        self._sku = sku
        self._name = name
        self._category = category
        self._unit_price = unit_price

    @property
    def sku(self) -> str:
        """Return the product SKU."""
        return self._sku

    @property
    def name(self) -> str:
        """Return the product name."""
        return self._name

    @property
    def category(self) -> Category:
        """Return the product category."""
        return self._category

    @property
    def unit_price(self) -> Money:
        """Return the product unit price."""
        return self._unit_price

    def identity(self) -> str:
        """Return the SKU as the entity identity."""
        return self._sku

    def with_price(self, new_price: Money) -> Product:
        """Return a copy of this product with an updated unit price."""
        if not isinstance(new_price, Money):
            raise TypeError("new_price must be Money")
        return Product(self._sku, self._name, self._category, new_price)

    @classmethod
    def from_dict(cls, data: Mapping[str, object]) -> Product:
        """Build a product from a mapping with keys sku, name, category, unit_price_cents."""
        for key in ("sku", "name", "category", "unit_price_cents"):
            if key not in data:
                raise KeyError(key)
        raw_category = data["category"]
        if isinstance(raw_category, str):
            category = Category.from_label(raw_category)
        elif isinstance(raw_category, Category):
            category = raw_category
        else:
            raise TypeError("category must be str or Category")
        unit_price = Money(data["unit_price_cents"])
        return cls(data["sku"], data["name"], category, unit_price)

    @staticmethod
    def is_valid_name(name: str) -> bool:
        """Return True if ``name`` is a string of 1..80 non-blank characters."""
        if not isinstance(name, str):
            return False
        return 1 <= len(name.strip()) <= 80
